// Create custom registry
public static final ResourceKey<Registry<MyObject>> MY_REGISTRY =
    ResourceKey.createRegistryKey(new ResourceLocation(MODID, "my_objects"));

@SubscribeEvent
public static void createRegistry(NewRegistryEvent event) {
    RegistryBuilder<MyObject> builder = new RegistryBuilder<>();
    builder.setName(new ResourceLocation(MODID, "my_objects"));
    builder.setDefaultKey(new ResourceLocation(MODID, "default"));
    event.create(builder);
}
